"""Add PowerPoint Morph / Fade transitions to a .pptx generated by pptxgenjs.

Morph is a p159 (2015/09) extension wrapped in mc:AlternateContent with a fade
fallback. The transition lives on the arriving slide, after </p:clrMapOvr>.

Morph matches objects by type and by the `name` attribute. Give the same
`objectName: "!!earth"` to the shapes that should travel; one `!!` name per slide.

Usage:
  python add_morph.py deck.pptx --dur 500 --fade 2,3,6,7,8,9,10,11 --fade-dur 100
  python add_morph.py deck.pptx --durations '{"4":500,"5":500}'
"""
import argparse
import json
import os
import re
import sys
import zipfile
from pathlib import Path

MC = "http://schemas.openxmlformats.org/markup-compatibility/2006"
P14 = "http://schemas.microsoft.com/office/powerpoint/2010/main"
P159 = "http://schemas.microsoft.com/office/powerpoint/2015/09/main"


def morph_block(dur_ms: int, option: str) -> str:
    return (
        f'<mc:AlternateContent xmlns:mc="{MC}">'
        f'<mc:Choice xmlns:p14="{P14}" xmlns:p159="{P159}" Requires="p14 p159">'
        f'<p:transition spd="slow" p14:dur="{int(dur_ms)}" advClick="1">'
        f'<p159:morph option="{option}"/>'
        f'</p:transition>'
        f'</mc:Choice>'
        f'<mc:Fallback>'
        f'<p:transition spd="slow" advClick="1"><p:fade/></p:transition>'
        f'</mc:Fallback>'
        f'</mc:AlternateContent>'
    )


def fade_block(dur_ms: int = 100) -> str:
    return (
        f'<mc:AlternateContent xmlns:mc="{MC}">'
        f'<mc:Choice xmlns:p14="{P14}" Requires="p14">'
        f'<p:transition spd="fast" p14:dur="{int(dur_ms)}" advClick="1"><p:fade/></p:transition>'
        f'</mc:Choice>'
        f'<mc:Fallback>'
        f'<p:transition spd="fast" advClick="1"><p:fade/></p:transition>'
        f'</mc:Fallback>'
        f'</mc:AlternateContent>'
    )


def insert_after(xml: str, block: str, slide_no: int) -> str:
    anchor = "</p:clrMapOvr>"
    if anchor in xml:
        return xml.replace(anchor, anchor + block, 1)
    m = re.search(r"</p:cSld>", xml)
    if not m:
        raise ValueError(f"no insertion anchor on slide {slide_no}")
    return xml[: m.end()] + block + xml[m.end():]


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("pptx")
    ap.add_argument("--dur", type=int, default=500, help="morph duration in ms (default 500)")
    ap.add_argument("--fade-dur", type=int, default=100, help="fade duration in ms (default 100)")
    ap.add_argument("--option", default="byObject", choices=["byObject", "byWord", "byChar"])
    ap.add_argument("--by-word", default="", help="comma separated arriving slides to use byWord")
    ap.add_argument("--durations", default="", help='json {slideNo: ms}, overrides --dur')
    ap.add_argument("--fade", default="", help="comma separated arriving slides that get a plain fade")
    ap.add_argument("--out", default="", help="output path; default: overwrite in place")
    args = ap.parse_args()

    src = Path(args.pptx)
    out = Path(args.out) if args.out else src
    by_word = {int(x) for x in args.by_word.split(",") if x.strip()}
    durations = {int(k): int(v) for k, v in json.loads(args.durations or "{}").items()}
    fades = {int(x) for x in args.fade.split(",") if x.strip()}

    with zipfile.ZipFile(src) as zin:
        names = [n for n in zin.namelist() if not n.endswith("/")]
        data = {n: zin.read(n) for n in names}

    slides = sorted(
        (n for n in names if re.fullmatch(r"ppt/slides/slide\d+\.xml", n)),
        key=lambda n: int(re.search(r"slide(\d+)\.xml", n).group(1)),
    )

    morph_count = 0
    fade_count = 0
    for name in slides:
        n = int(re.search(r"slide(\d+)\.xml", name).group(1))
        if n == 1:
            continue
        xml = data[name].decode("utf-8")
        if "p159:morph" in xml or "<p:fade/>" in xml:
            continue
        if n in fades:
            block = fade_block(args.fade_dur)
            fade_count += 1
        else:
            opt = "byWord" if n in by_word else args.option
            block = morph_block(durations.get(n, args.dur), opt)
            morph_count += 1
        data[name] = insert_after(xml, block, n).encode("utf-8")

    tmp = out.with_name(out.stem + ".tmp.pptx")
    try:
        with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
            for name in names:
                zout.writestr(name, data[name])
        os.replace(tmp, out)
    finally:
        if tmp.exists():
            tmp.unlink()

    print(f"transitions: {morph_count} morph, {fade_count} fade -> {out}")


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(f"add_morph: {e}", file=sys.stderr)
        sys.exit(1)
